        WHERE c.conrelid = to_regclass('banking.bank_accounts') AND c.contype = 'f' AND a.attname = 'bank_id'
    ) THEN
        ALTER TABLE banking.bank_accounts ADD CONSTRAINT fk_bank_accounts_bank_id FOREIGN KEY (bank_id) REFERENCES banking.banks (id) NOT VALID;
